import { invalidRequestBody, invalidCursor } from "../problems.mjs";

// Cursor pagination shared by the three listings (Appendix A): `limit` and
// `cursor` query parameters, and a `next` link on every page but the last.

const DEFAULT_LIMIT = 100;
const MAX_LIMIT = 1000;

export function pageLimit(req) {
  const raw = req.query.limit;
  if (raw === undefined) {
    return DEFAULT_LIMIT;
  }
  const limit = Number(raw);
  if (!Number.isInteger(limit) || limit < 1 || limit > MAX_LIMIT) {
    throw invalidRequestBody(`"limit" must be an integer between 1 and ${MAX_LIMIT}.`);
  }
  return limit;
}

export function nextLink(url, cursor, limit) {
  return `${url}?cursor=${encodeURIComponent(cursor)}&limit=${limit}`;
}

// A cursor over an in-memory list: the offset of the next item, encoded.
export function offsetCursor(offset) {
  return Buffer.from(JSON.stringify({ offset })).toString("base64url");
}

export function readOffsetCursor(cursor) {
  if (cursor === undefined) {
    return 0;
  }
  try {
    const { offset } = JSON.parse(Buffer.from(cursor, "base64url").toString("utf8"));
    if (!Number.isInteger(offset) || offset < 0) {
      throw new Error("bad offset");
    }
    return offset;
  } catch {
    throw invalidCursor("The cursor was not issued by this listing.");
  }
}
